// ── ClaimFlow signed status links ─────────────────────────────────
// Claim references are sequential, so the Status API needs proof the caller was given the
// link: t = first 32 hex chars of HMAC-SHA256(CLAIMFLOW_STATUS_LINK_KEY, claim_ref).
// Copied into the Code nodes that build or check links (same pattern as pii-crypto.js).
const linkCrypto = require('crypto');

function statusToken(claimRef, env) {
  const key = Buffer.from(String(env.CLAIMFLOW_STATUS_LINK_KEY || ''), 'base64');
  if (key.length < 32) throw new Error('CLAIMFLOW_STATUS_LINK_KEY must be at least 32 random bytes, base64-encoded');
  return linkCrypto.createHmac('sha256', key).update(`status:${claimRef}`, 'utf8').digest('hex').slice(0, 32);
}

function statusUrl(claimRef, env) {
  return `${env.WEBHOOK_URL}webhook/claims/status?ref=${encodeURIComponent(claimRef)}&t=${statusToken(claimRef, env)}`;
}

// Constant-time comparison so response timing doesn't reveal how much of a token matched.
function statusTokenValid(claimRef, token, env) {
  const expected = Buffer.from(statusToken(claimRef, env), 'utf8');
  const given = Buffer.from(String(token || ''), 'utf8');
  return given.length === expected.length && linkCrypto.timingSafeEqual(given, expected);
}

// ── Validate status request ──────────────────────────────────────
// A wrong or missing token gets the same answer as an unknown claim (404), so the API never
// confirms that a reference exists. The token check is constant-time (links.js).
const q = $input.first().json.query || {};
const ref = String(q.ref || '').trim().toUpperCase();
if (!/^CLM-\d{4}-\d{6}$/.test(ref)) {
  return [{ json: { result: 'bad_request', error: 'bad_request', message: 'ref is required and must look like CLM-YYYY-NNNNNN' } }];
}
if (!statusTokenValid(ref, q.t, $env)) return [{ json: { result: 'not_found', ref } }];
return [{ json: { result: 'ok', ref } }];

// ── Map to the public view of a claim ────────────────────────────
// Internal statuses and events become neutral public ones: a claim under fraud review looks
// exactly like one in the normal queue (no tipping off). No scores, flags or names.
const r = $input.first().json;
if (!r.claim_ref) return [{ json: { found: false } }];
const STATUS = {
  received: ['received', 'Received'],
  in_standard_queue: ['under_review', 'Under review'],
  pending_fraud_review: ['under_review', 'Under review'],
  pending_manual_review: ['under_review', 'Under review'],
  approved_for_assessment: ['approved_for_assessment', 'Approved for assessment'],
  more_info_required: ['more_info_required', 'More information needed'],
  rejected: ['not_accepted', 'Not accepted'],
  rejected_ineligible: ['not_accepted', 'Not accepted'],
  closed: ['closed', 'Closed'],
};
const EVENT = {
  received: ['received', 'Claim received'], routed: ['assessed', 'Claim assessed'],
  review_decision: ['review_completed', 'Review completed'], notification_sent: ['email_sent', 'We emailed you'],
  rejected_ineligible: ['not_accepted', 'Claim not accepted'], status_changed: ['status_updated', 'Status updated'],
};
const iso = (v) => (v ? DateTime.fromJSDate(new Date(v)).setZone('Africa/Johannesburg').toISO({ suppressMilliseconds: true }) : null);
const [status, status_label] = STATUS[r.status] || ['under_review', 'Under review'];
return [{ json: {
  found: true,
  response: {
    claim_ref: r.claim_ref, status, status_label, product: r.product, incident_date: r.incident_date,
    submitted_at: iso(r.reported_at), last_updated: iso(r.updated_at),
    timeline: (r.timeline || []).filter((t) => EVENT[t.event]).map((t) => ({ event: EVENT[t.event][0], label: EVENT[t.event][1], at: iso(t.at) })),
  },
} }];
